css:
.print-format { padding: 15mm 12mm; margin: 0; font-family: Arial, Helvetica, sans-serif; color: #000; }
.print-format .wo-header { text-align: center; margin-bottom: 10px; }
.print-format .wo-logo { max-height: 60px; max-width: 220px; margin: 0 auto 6px; display: block; }
.print-format .wo-company { font-size: 15pt; font-weight: bold; color: #002060; letter-spacing: 0.5px; }
.print-format .wo-title { font-size: 13pt; font-weight: bold; color: #fff; background: #002060; padding: 6px; margin: 12px 0; text-align: center; letter-spacing: 1px; }
.print-format table.wo-table { width: 100%; border-collapse: collapse; margin-bottom: 6px; table-layout: fixed; }
.print-format table.wo-table td { border: 1px solid #000; padding: 6px 8px; vertical-align: middle; font-size: 10pt; box-sizing: border-box; }
.print-format table.wo-table td.label { width: 30%; font-weight: bold; background: #f2f2f2; white-space: nowrap; }
.print-format table.wo-table td.value { width: 70%; word-wrap: break-word; }
.print-format table.wo-table td.section { background: #002060; color: #fff; font-weight: bold; padding: 5px 8px; font-size: 10pt; letter-spacing: 0.5px; border: 1px solid #002060; }
.print-format .wo-jc-table { width: 100%; border-collapse: collapse; margin-top: 4px; margin-bottom: 12px; }
.print-format .wo-jc-table th { border: 1px solid #000; padding: 5px 6px; background: #002060; color: #fff; font-weight: bold; font-size: 9pt; text-align: left; }
.print-format .wo-jc-table td { border: 1px solid #000; padding: 5px 6px; font-size: 9pt; vertical-align: middle; }
.print-format .wo-footer { text-align: center; font-size: 8pt; color: #555; margin-top: 14px; border-top: 1px solid #ccc; padding-top: 6px; }
